// build.js — regenerates worker.js from index.html
// Usage: node build.js
// The apex worker (Cloudflare script "soft-limit-2cfc") serves index.html as a
// base64 blob. Edit index.html, run this, then deploy worker.js to Cloudflare.
// Serves CORE PWA assets (/manifest.json /icon.svg /icon-192.png /icon-512.png /sw.js)
// and DECK PWA assets (/m-deck.json /sw-deck.js /dk-icon-192.png /dk-icon-512.png)
// so both surfaces pass Chrome Android installability (PNG icons + service worker).
const fs = require("fs");
const html = fs.readFileSync(__dirname + "/index.html", "utf8");
const b64 = Buffer.from(html, "utf8").toString("base64");

const manifest = JSON.stringify({
  name: "DMOWBRAY CORE",
  short_name: "CORE",
  id: "/",
  start_url: "/",
  scope: "/",
  display: "standalone",
  background_color: "#07090e",
  theme_color: "#07090e",
  icons: [
    { src: "/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
    { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
    { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    { src: "/icon.svg", sizes: "any", type: "image/svg+xml", purpose: "any" }
  ]
});

const deckManifest = JSON.stringify({
  name: "DENMOW DECK",
  short_name: "DECK",
  id: "/deck",
  start_url: "/deck",
  scope: "/deck",
  display: "standalone",
  background_color: "#0b0e0d",
  theme_color: "#0b0e0d",
  icons: [
    { src: "/dk-icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
    { src: "/dk-icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
    { src: "/dk-icon-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" }
  ]
});

const icon = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><rect width="512" height="512" rx="96" fill="#07090e"/><path d="M40 330 C140 250 200 390 300 310 S460 240 500 290" fill="none" stroke="#2dd4bf" stroke-width="22" stroke-linecap="round" opacity="0.9"/><path d="M20 240 C120 170 210 300 320 220 S450 160 500 200" fill="none" stroke="#60a5fa" stroke-width="18" stroke-linecap="round" opacity="0.75"/><path d="M50 410 C160 350 240 460 350 390 S470 340 500 370" fill="none" stroke="#a78bfa" stroke-width="16" stroke-linecap="round" opacity="0.7"/><path d="M300 70 L258 160 L296 160 L252 250 L342 140 L302 140 L344 70 Z" fill="#eef2ff" opacity="0.95"/></svg>';

const PNG192 = "";
const PNG512 = "";
const DPNG192 = "";
const DPNG512 = "";


const mdeck = JSON.stringify({
  name: "DENMOW Deck",
  short_name: "DECK",
  id: "/deck",
  start_url: "/deck",
  scope: "/deck",
  display: "standalone",
  background_color: "#0b0e0d",
  theme_color: "#0b0e0d",
  icons: [
    { src: "/deck-icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
    { src: "/deck-icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
    { src: "/deck-icon-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" }
  ]
});
const DECK192 = "";
const DECK512 = "";

// no-op service worker: satisfies installability, does NOT cache or intercept
const sw = 'self.addEventListener("install",function(){self.skipWaiting();});self.addEventListener("activate",function(e){e.waitUntil(self.clients.claim());});self.addEventListener("fetch",function(){});';

const worker =
'addEventListener("fetch", function (e) { e.respondWith(serve(e.request)); });\n' +
'var MANIFEST = ' + JSON.stringify(manifest) + ';\n' +
'var DECKMAN = ' + JSON.stringify(deckManifest) + ';\n' +
'var ICON = ' + JSON.stringify(icon) + ';\n' +
'var PNG192 = ' + JSON.stringify(PNG192) + ';\n' +
'var PNG512 = ' + JSON.stringify(PNG512) + ';\n' +
'var DPNG192 = ' + JSON.stringify(DPNG192) + ';\n' +
'var DPNG512 = ' + JSON.stringify(DPNG512) + ';\n' +
'var SW = ' + JSON.stringify(sw) + ';\n' +
'var MDECK = ' + JSON.stringify(mdeck) + ';\n' +
'var DECK192 = ' + JSON.stringify(DECK192) + ';\n' +
'var DECK512 = ' + JSON.stringify(DECK512) + ';\n' +
'function bin(b64) {\n' +
'  var s = atob(b64);\n' +
'  var b = new Uint8Array(s.length);\n' +
'  for (var i = 0; i < s.length; i++) b[i] = s.charCodeAt(i);\n' +
'  return b;\n' +
'}\n' +
'function serve(req) {\n' +
'  var p = "";\n' +
'  try { p = new URL(req.url).pathname; } catch (err) {}\n' +
'  if (p === "/manifest.json") return new Response(MANIFEST, { headers: { "content-type": "application/manifest+json", "cache-control": "no-store" } });\n' +
'  if (p === "/m-deck.json") return new Response(DECKMAN, { headers: { "content-type": "application/manifest+json", "cache-control": "no-store" } });\n' +
'  if (p === "/icon.svg") return new Response(ICON, { headers: { "content-type": "image/svg+xml", "cache-control": "max-age=86400" } });\n' +
'  if (p === "/icon-192.png") return new Response(bin(PNG192), { headers: { "content-type": "image/png", "cache-control": "max-age=86400" } });\n' +
'  if (p === "/icon-512.png") return new Response(bin(PNG512), { headers: { "content-type": "image/png", "cache-control": "max-age=86400" } });\n' +
'  if (p === "/dk-icon-192.png") return new Response(bin(DPNG192), { headers: { "content-type": "image/png", "cache-control": "max-age=86400" } });\n' +
'  if (p === "/dk-icon-512.png") return new Response(bin(DPNG512), { headers: { "content-type": "image/png", "cache-control": "max-age=86400" } });\n' +
'  if (p === "/m-deck.json") return new Response(MDECK, { headers: { "content-type": "application/manifest+json", "cache-control": "no-store" } });\n' +
'  if (p === "/sw-deck.js") return new Response(SW, { headers: { "content-type": "application/javascript", "cache-control": "no-store" } });\n' +
'  if (p === "/dk-icon-192.png" || p === "/deck-icon-192.png") return new Response(bin(DECK192), { headers: { "content-type": "image/png", "cache-control": "max-age=86400" } });\n' +
'  if (p === "/dk-icon-512.png" || p === "/deck-icon-512.png") return new Response(bin(DECK512), { headers: { "content-type": "image/png", "cache-control": "max-age=86400" } });\n' +
'  if (p === "/sw.js") return new Response(SW, { headers: { "content-type": "application/javascript", "cache-control": "no-store" } });\n' +
'  if (p === "/sw-deck.js") return new Response(SW, { headers: { "content-type": "application/javascript", "cache-control": "no-store", "Service-Worker-Allowed": "/deck" } });\n' +
'  var b64 = "__HTMLB64__";\n' +
'  var html = new TextDecoder("utf-8").decode(bin(b64));\n' +
'  return new Response(html, { headers: { "content-type": "text/html;charset=UTF-8", "cache-control": "no-store" } });\n' +
'}';
fs.writeFileSync(__dirname + "/worker.js", worker.replace("__HTMLB64__", b64));
console.log("worker.js regenerated — html " + html.length + " chars");
